namespace ScoreFoot.Data;

// Ids of League, Team, Player and Fixture are API-Football ids, not generated by the database.

public class League
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public string? Country { get; set; }
    public string? LogoPath { get; set; }
}

public class Team
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string NameSearch { get; set; }
    public string? Code { get; set; }
    public string? Country { get; set; }
    public string? LogoUrl { get; set; }
    public string? LogoPath { get; set; }
}

public class Player
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string NameSearch { get; set; }
    public string? FirstName { get; set; }
    public string? LastName { get; set; }
    public DateOnly? BirthDate { get; set; }
    public string? Nationality { get; set; }
    public int? HeightCm { get; set; }
    public int? WeightKg { get; set; }
    public string? PhotoUrl { get; set; }
    public string? PhotoPath { get; set; }
}

/// <summary>Stats shared by a season line and a single match line. Null means the API gave no value.</summary>
public abstract class StatLine
{
    public string? Position { get; set; }
    public int? Minutes { get; set; }
    public decimal? Rating { get; set; }
    public int? Goals { get; set; }
    public int? Assists { get; set; }
    public int? GoalsConceded { get; set; }
    public int? Saves { get; set; }
    public int? ShotsTotal { get; set; }
    public int? ShotsOnTarget { get; set; }
    public int? PassesTotal { get; set; }
    public int? PassesKey { get; set; }
    public int? PassAccuracy { get; set; }
    public int? Tackles { get; set; }
    public int? Blocks { get; set; }
    public int? Interceptions { get; set; }
    public int? DuelsTotal { get; set; }
    public int? DuelsWon { get; set; }
    public int? DribblesAttempts { get; set; }
    public int? DribblesSuccess { get; set; }
    public int? FoulsDrawn { get; set; }
    public int? FoulsCommitted { get; set; }
    public int? YellowCards { get; set; }
    public int? RedCards { get; set; }
    public int? PenaltiesScored { get; set; }
    public int? PenaltiesMissed { get; set; }
}

/// <summary>One row per player, club, league and season (a mid-season transfer gives two rows).</summary>
public class PlayerSeasonStat : StatLine
{
    public long Id { get; set; }
    public int PlayerId { get; set; }
    public int TeamId { get; set; }
    public int LeagueId { get; set; }
    public int Season { get; set; }
    public int? Appearances { get; set; }
    public int? Lineups { get; set; }

    public Player Player { get; set; } = null!;
    public Team Team { get; set; } = null!;
    public League League { get; set; } = null!;
}

public class Fixture
{
    public int Id { get; set; }
    public int LeagueId { get; set; }
    public int Season { get; set; }
    public required string Round { get; set; }
    public DateTimeOffset KickoffUtc { get; set; }
    public required string Status { get; set; }
    public int HomeTeamId { get; set; }
    public int AwayTeamId { get; set; }
    public int? HomeGoals { get; set; }
    public int? AwayGoals { get; set; }

    public League League { get; set; } = null!;
    public Team HomeTeam { get; set; } = null!;
    public Team AwayTeam { get; set; } = null!;
}

public class FixturePlayerStat : StatLine
{
    public long Id { get; set; }
    public int FixtureId { get; set; }
    public int PlayerId { get; set; }
    public int TeamId { get; set; }
    public bool Substitute { get; set; }
    public bool Captain { get; set; }

    public Fixture Fixture { get; set; } = null!;
    public Player Player { get; set; } = null!;
    public Team Team { get; set; } = null!;
}

public class Standing
{
    public long Id { get; set; }
    public int LeagueId { get; set; }
    public int Season { get; set; }
    public int TeamId { get; set; }
    public int Rank { get; set; }
    public int Points { get; set; }
    public int Played { get; set; }
    public int Won { get; set; }
    public int Drawn { get; set; }
    public int Lost { get; set; }
    public int GoalsFor { get; set; }
    public int GoalsAgainst { get; set; }
    public string? Form { get; set; }
    public string? Description { get; set; }

    public League League { get; set; } = null!;
    public Team Team { get; set; } = null!;
}

/// <summary>Every API answer, kept so data can be re-parsed without spending quota.</summary>
public class RawResponse
{
    public long Id { get; set; }
    public required string Endpoint { get; set; }
    public required string Parameters { get; set; }
    public DateTimeOffset FetchedAt { get; set; }
    public required string Body { get; set; }
}

public enum SyncTaskType { Teams, Standings, Fixtures, FixtureDetails, Players }

public enum SyncTaskStatus { Pending, Done, Failed }

public class SyncTask
{
    public long Id { get; set; }
    public SyncTaskType Type { get; set; }
    public int LeagueId { get; set; }
    public int Season { get; set; }
    public int? Page { get; set; }
    /// <summary>Dash-separated fixture ids, as the API expects them.</summary>
    public string? FixtureIds { get; set; }
    public SyncTaskStatus Status { get; set; }
    public int Attempts { get; set; }
    public string? LastError { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; }
}

public class ApiCall
{
    public long Id { get; set; }
    public DateTimeOffset CalledAt { get; set; }
    public required string Endpoint { get; set; }
    public int HttpStatus { get; set; }
}
